28	/**
29	 * POJO object wrapper for metadata of a given key/file. This class wraps a KeyInfo protobuf
30	 * object and delegates most accessors to it.
31	 */
32	public final class KeyEntityInfoProtoWrapper {
33	
34	  private final OzoneManagerProtocolProtos.KeyInfo keyInfoProto;
35	
36	  /** This is key table key of rocksDB and will help UI to implement pagination
37	   * where UI will use the last record key to send in API as preKeyPrefix. */
38	  @JsonProperty("key")
39	  private String key;
40	
41	  /** Path of a key/file. */
42	  @JsonProperty("path")
43	  private String path;
44	
45	  @JsonProperty("replicatedSize")
46	  private final long replicatedSize;
47	
48	  @JsonProperty("replicationInfo")
49	  private final ReplicationConfig replicationConfig;
50	
51	  private KeyEntityInfoProtoWrapper(OzoneManagerProtocolProtos.KeyInfo proto) {
52	    keyInfoProto = proto;
53	    replicationConfig = ReplicationConfig.fromProto(proto.getType(), proto.getFactor(),
54	        proto.getEcReplicationConfig());
55	    this.replicatedSize = QuotaUtil.getReplicatedSize(getSize(), getReplicationConfig());
56	  }
57	
58	  public static Codec<KeyEntityInfoProtoWrapper> getCodec() {
59	    return new DelegatedCodec<>(
60	        Proto2Codec.get(OzoneManagerProtocolProtos.KeyInfo.getDefaultInstance()),
61	        KeyEntityInfoProtoWrapper::getFromProtobuf,
62	        KeyEntityInfoProtoWrapper::toProtobuf,
63	        KeyEntityInfoProtoWrapper.class);
64	  }
65	
66	  public static KeyEntityInfoProtoWrapper getFromProtobuf(OzoneManagerProtocolProtos.KeyInfo keyInfo) {
67	    return new KeyEntityInfoProtoWrapper(keyInfo);
68	  }
69	
70	  public OzoneManagerProtocolProtos.KeyInfo toProtobuf() {
71	    throw new UnsupportedOperationException("This method is not supported.");
72	  }
73	
74	  @JsonProperty("key")
75	  public String getKey() {
76	    if (key == null) {
77	      throw new IllegalStateException("Key must be set to correctly serialize this object.");
78	    }
79	    return key;
80	  }
81	
82	  public void setKey(String key) {
83	    this.key = key;
84	  }
85	
86	  @JsonProperty("path")
87	  public String getPath() {
88	    if (path == null) {
89	      throw new IllegalStateException("Path must be set to correctly serialize this object.");
90	    }
91	    return path;
92	  }
93	
94	  public void setPath(String path) {
95	    this.path = path;
96	  }
97	
98	  @JsonProperty("size")
99	  public long getSize() {
100	    return keyInfoProto.getDataSize();
101	  }
102	
103	  @JsonProperty("replicatedSize")
104	  public long getReplicatedSize() {
105	    return replicatedSize;
106	  }
107	
108	  @JsonProperty("replicationInfo")
109	  public ReplicationConfig getReplicationConfig() {
110	    return replicationConfig;
111	  }
112	
113	  @JsonProperty("creationTime")
114	  public long getCreationTime() {
115	    return keyInfoProto.getCreationTime();
116	  }
117	
118	  @JsonProperty("modificationTime")
119	  public long getModificationTime() {
120	    return keyInfoProto.getModificationTime();
121	  }
122	
123	  @JsonProperty("isKey")
124	  public boolean getIsKey() {
125	    return keyInfoProto.getIsFile();
126	  }
127	
128	  public long getParentId() {
129	    return keyInfoProto.getParentID();
130	  }
131	
132	  public String getVolumeName() {
133	    return keyInfoProto.getVolumeName();
134	  }
135	
136	  public String getBucketName() {
137	    return keyInfoProto.getBucketName();
138	  }
139	
140	  /** Returns the key name of the key stored in the OM Key Info object. */
141	  public String getKeyName() {
142	    return keyInfoProto.getKeyName();
143	  }
