52	/**
53	 * Recon's implementation of the OM Metadata manager. By extending and
54	 * relying on the OmMetadataManagerImpl, we can make sure all changes made to
55	 * schema in OM will be automatically picked up by Recon.
56	 */
57	@Singleton
58	public class ReconOmMetadataManagerImpl extends OmMetadataManagerImpl
59	    implements ReconOMMetadataManager {
60	
61	  private static final Logger LOG =
62	      LoggerFactory.getLogger(ReconOmMetadataManagerImpl.class);
63	
64	  private OzoneConfiguration ozoneConfiguration;
65	  private ReconUtils reconUtils;
66	  private boolean omTablesInitialized = false;
67	
68	  @Inject
69	  public ReconOmMetadataManagerImpl(OzoneConfiguration configuration,
70	                                    ReconUtils reconUtils) {
71	    this.reconUtils = reconUtils;
72	    this.ozoneConfiguration = configuration;
73	  }
74	
75	  @Override
76	  public void start(OzoneConfiguration configuration) throws IOException {
77	    LOG.info("Starting ReconOMMetadataManagerImpl");
78	    File reconDbDir =
79	        reconUtils.getReconDbDir(configuration, OZONE_RECON_OM_SNAPSHOT_DB_DIR);
80	    File lastKnownOMSnapshot =
81	        reconUtils.getLastKnownDB(reconDbDir, RECON_OM_SNAPSHOT_DB);
82	    if (lastKnownOMSnapshot != null) {
83	      LOG.info("Last known snapshot for OM : {}",
84	          lastKnownOMSnapshot.getAbsolutePath());
85	      initializeNewRdbStore(lastKnownOMSnapshot);
86	    }
87	  }
88	
89	  /**
90	   * Replace existing DB instance with new one.
91	   *
92	   * @param dbFile new DB file location.
93	   */
94	  private void initializeNewRdbStore(File dbFile) throws IOException {
95	    try {
96	      setStore(DBStoreBuilder.newBuilder(ozoneConfiguration, OMDBDefinition.get(), dbFile).build());
97	      LOG.info("Created OM DB handle from snapshot at {}.",
98	          dbFile.getAbsolutePath());
99	    } catch (IOException ioEx) {
100	      LOG.error("Unable to initialize Recon OM DB snapshot store.", ioEx);
101	    }
102	    if (getStore() != null) {
103	      initializeOmTables(TableCache.CacheType.FULL_CACHE, true);
104	      omTablesInitialized = true;
105	    }
106	  }
107	
108	  @Override
109	  public Table<String, KeyEntityInfoProtoWrapper> getKeyTableLite(BucketLayout bucketLayout) throws IOException {
110	    String tableName = bucketLayout.isFileSystemOptimized() ? OMDBDefinition.FILE_TABLE : OMDBDefinition.KEY_TABLE;
111	    return getStore().getTable(tableName, StringCodec.get(), KeyEntityInfoProtoWrapper.getCodec());
112	  }
113	
114	  @Override
115	  public void updateOmDB(File newDbLocation) throws IOException {
116	    if (getStore() != null) {
117	      File oldDBLocation = getStore().getDbLocation();
118	      if (oldDBLocation.exists()) {
119	        LOG.info("Cleaning up old OM snapshot db at {}.",
120	            oldDBLocation.getAbsolutePath());
121	        FileUtils.deleteDirectory(oldDBLocation);
122	      }
123	    }
124	    DBStore current = getStore();
125	    try {
126	      initializeNewRdbStore(newDbLocation);
127	    } finally {
128	      // Always close DBStore if it's replaced.
129	      if (current != null && current != getStore()) {
130	        current.close();
131	      }
132	    }
133	  }
134	
135	  @Override
136	  public long getLastSequenceNumberFromDB() {
137	    RDBStore rocksDBStore = (RDBStore) getStore();
138	    if (null == rocksDBStore) {
139	      return 0;
140	    } else {
141	      try {
142	        return rocksDBStore.getDb().getLatestSequenceNumber();
143	      } catch (IOException e) {
144	        return 0;
145	      }
146	    }
147	  }
